<template>
  <div id="networkScanResult">
    <h2>Network Scan Result</h2>
    <div id="anomaliesSection">
      <div id="targetAnomaly">
        <p>The target is <b><span id="ip"></span></b>.</p>
        <p>The scan method used is native-net.</p>
      </div>
      <div id="openPortsAnomaly">
        <p>Open ports: {openPorts}</p>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "networkScanResult",
  data() {
    return {
      scanMethod: "native-net",
      openPorts: [135, 445]
    };
  },
  methods: {
    analyzeNetworkScan(result) {
      this.openPorts = [];
      for (let port of result.openPorts) {
        if (!this.openPorts.includes(port)) {
          this.openPorts.push(port);
        }
      }
    }
  },
  mounted() {
    const self = this;
    setTimeout(() => {
      let anomalyCheck = false;
      const scanResult = JSON.parse(this.$data.scanMethod);
      Object.keys(scanResult).forEach((target) => {
        if (scanResult[target].includes(self.target)) {
          anomalyCheck = true;
          break;
        }
      });
      if (!anomalyCheck) {
        self.analyzeNetworkScan();
      }
    }, 1000); // Delay of 1 second before analyzing the network scan result
  },
  updated() {
    if (this.$el.id === "networkScanResult") {
      this.analyzeNetworkScan(this.$data.scanMethod);
    }
  }
};
</script>

